insert into public.news (title, summary, body, scope, source, url, published_at)
select v.title, v.summary, v.body, v.scope, v.source, v.url, v.published_at::timestamptz
from (values
  ($q1$نمو الناتج المحلي الإجمالي لسلطنة عُمان بنسبة 5.1% في الربع الثاني من 2026$q1$, $q2$سجّل الناتج المحلي الإجمالي بالأسعار الثابتة نموًّا بنسبة 5.1% خلال الربع الثاني من عام 2026م، مدفوعًا بنموّ الأنشطة النفطية.$q2$, $q3$سجّل الناتج المحلي الإجمالي لسلطنة عُمان بالأسعار الثابتة نموًّا بنسبة 5.1% خلال الربع الثاني من عام 2026م، ليبلغ نحو 9.9 مليارات ريال عُماني، مقابل نحو 9.4 مليارات ريال في الربع نفسه من عام 2025م.

ونمت الأنشطة النفطية بنسبة 14.7% لتصل إلى نحو 3.4 مليارات ريال عُماني في الربع الثاني من 2026م.$q3$, 'oman', $q4$جريدة عُمان$q4$, $q5$https://www.omandaily.om/article/1211862$q5$, '2026-10-04 12:00:00+04'),
  ($q11$جلالة السلطان يصدر مرسومين سلطانيين$q11$, $q12$أصدر حضرة صاحب الجلالة السلطان هيثم بن طارق المعظّم مرسومين سلطانيين يتعلقان باتفاقية مع جمهورية رواندا وبميثاق منظمة التعاون الإسلامي.$q12$, $q13$أصدر حضرة صاحب الجلالة السلطان هيثم بن طارق المعظّم، حفظه الله ورعاه، مرسومين سلطانيين: تضمّن أحدهما التصديق على اتفاقية بين حكومة سلطنة عُمان وحكومة جمهورية رواندا، وتعلّق الآخر بتعديل ميثاق منظمة التعاون الإسلامي.$q13$, 'oman', $q14$جريدة عُمان$q14$, $q15$https://www.omandaily.om/article/1211871$q15$, '2026-10-04 11:52:00+04'),
  ($q21$عُمان تستضيف اليوم العالمي للموئل 2026 اعتبارًا من الإثنين$q21$, $q22$تستضيف مسقط اليوم العالمي للموئل بالشراكة مع الأمم المتحدة تحت شعار «سكن لائق للجميع»، بالتزامن مع معرض ومؤتمر العمران من 5 إلى 8 أكتوبر.$q22$, $q23$تستضيف سلطنة عُمان اليوم العالمي للموئل 2026 بالشراكة مع برنامج الأمم المتحدة للمستوطنات البشرية (الموئل)، تحت شعار «سكن لائق للجميع»، وذلك بالتزامن مع النسخة السادسة من معرض ومؤتمر العمران والبيت والبناء، من 5 إلى 8 أكتوبر في مركز عُمان للمؤتمرات والمعارض.

ويشارك وفد أممي برئاسة أناكلاوديا روسباخ، المديرة التنفيذية لبرنامج الموئل، إلى جانب مشاركين من نحو 50 دولة. وبحسب ما نشرته صحيفة «الرؤية» يضم المعرض 220 عارضًا و65 مطورًا عقاريًا و90 متحدثًا و100 ورقة عمل.$q23$, 'oman', $q24$الرؤية$q24$, $q25$https://alroya.om/post/395195/220-%D8%B9%D8%A7%D8%B1%D8%B6-%D8%A7-%D9%8865-%D9%85%D8%B7%D9%88%D8%B1-%D8%A7-%D8%B9%D9%82%D8%A7%D8%B1%D9%8A-%D8%A7-%D9%8890-%D9%85%D8%AA%D8%AD%D8%AF%D8%AB-%D8%A7-%D9%88100-%D9%88%D8%B1%D9%82%D8%A9-%D8%B9%D9%85%D9%84-%D9%81%D9%8A-%D9%85%D8%B9%D8%B1%D8%B6-%D9%88%D9%85%D8%A4%D8%AA%D9%85%D8%B1-%D8%A7%D9%84%D8%B9%D9%85%D8%B1%D8%A7%D9%86-%D9%88%D8%A7%D9%84%D8%A8%D9%8A%D8%AA-%D9%88%D8%A7%D9%84%D8%A8%D9%86%D8%A7%D8%A1-%D8%A7%D9%84%D8%A5%D8%AB%D9%86%D9%8A%D9%86-%D8%A7%D9%84%D9%85%D9%82%D8%A8%D9%84$q25$, '2026-10-04 11:44:00+04'),
  ($q31$دخول قرارات الضريبة بمعدل الصفر على سلع غذائية وأدوية حيّز التنفيذ$q31$, $q32$بدأ منذ الأول من أكتوبر العمل بثلاثة قرارات إدارية لجهاز الضرائب تُخضع السلع الغذائية الأساسية والأدوية والتجهيزات الطبية لضريبة القيمة المضافة بمعدل الصفر.$q32$, $q33$بدأ اعتبارًا من الأول من أكتوبر 2026م العمل بثلاثة قرارات إدارية أصدرها جهاز الضرائب لتحديد السلع والمنتجات الخاضعة لضريبة القيمة المضافة بمعدل الصفر في المئة، وتشمل السلع الغذائية الأساسية، والأدوية والتجهيزات الطبية البشرية، والأدوية والتجهيزات الطبية البيطرية.

وتهدف القرارات إلى تعزيز منظومة الحماية الاجتماعية وتخفيف الأعباء المعيشية والمالية عن المواطنين والمقيمين، ودعم قطاعات الصحة والزراعة والثروة الحيوانية. وبحسب ما نشرته جريدة عُمان يبلغ عدد الأصناف والمنتجات المشمولة 1546 صنفًا.$q33$, 'oman', $q34$العربية$q34$, $q35$https://www.alarabiya.net/aswaq/economy/2026/09/27/%D8%B9-%D9%85%D8%A7%D9%86-%D8%AA%D8%B9%D9%81%D9%8A-%D8%B3%D9%84%D8%B9-%D8%A7-%D9%88%D9%85%D9%86%D8%AA%D8%AC%D8%A7%D8%AA-%D9%85%D9%86-%D8%B6%D8%B1%D9%8A%D8%A8%D8%A9-%D8%A7%D9%84%D9%82%D9%8A%D9%85%D8%A9-%D8%A7%D9%84%D9%85%D8%B6%D8%A7%D9%81%D8%A9-%D8%AD%D8%AF%D8%AF%D8%AA%D9%87%D8%A7-3-%D9%82%D8%B1%D8%A7%D8%B1%D8%A7%D8%AA-%D8%A7%D8%AF%D8%A7%D8%B1%D9%8A%D8%A9$q35$, '2026-10-04 11:36:00+04'),
  ($q41$كأس الخليج 27: الإمارات تتجاوز عُمان 1-0 وتبلغ النهائي$q41$, $q42$خسر منتخبنا الوطني أمام الإمارات بهدف دون ردّ في نصف نهائي كأس الخليج العربي السابعة والعشرين في جدّة.$q42$, $q43$خسر منتخب عُمان الأول لكرة القدم أمام منتخب الإمارات بهدف دون ردّ في نصف نهائي كأس الخليج العربي السابعة والعشرين، مساء السبت على استاد الأمير عبدالله الفيصل في جدّة.

سجّلت الإمارات هدف المباراة الوحيد في الدقيقة 22، وتصدّى حارس عُمان إبراهيم المخيني لركلة جزاء في الدقيقة 56. وتلتقي الإمارات منتخب السعودية في المباراة النهائية.$q43$, 'oman', $q44$خليج تايمز$q44$, $q45$https://www.khaleejtimes.com/sports/football/gulf-cup-dalics-uae-dream-of-trophy-after-beating-oman-in-semis$q45$, '2026-10-04 11:28:00+04'),
  ($q51$انطلاق مؤتمر عُمان للفضاء 2026 في مسقط$q51$, $q52$انطلقت أعمال المؤتمر الأحد بمشاركة نحو 70 مشاركًا من الجهات الحكومية وقطاع الفضاء والصناعة والأوساط الأكاديمية.$q52$, $q53$انطلقت أعمال مؤتمر عُمان للفضاء 2026 الأحد 4 أكتوبر بفندق إنتر سيتي مسقط، بمشاركة نحو 70 مشاركًا من ممثلي الجهات الحكومية والمؤسسات العاملة في قطاع الفضاء والصناعة والأوساط الأكاديمية.

تنظّم المؤتمرَ شركة «سبيس تك إن غلف» بشراكة استراتيجية مع وزارة النقل والاتصالات وتقنية المعلومات. ويناقش السياسة الوطنية والبرنامج التنفيذي لقطاع الفضاء العُماني ودورهما في دعم مستهدفات «رؤية عُمان 2040»، وآليات توظيف تطبيقات رصد الأرض والبيانات الفضائية في تطوير الخدمات الحكومية.$q53$, 'oman', $q54$وكالة الأنباء العُمانية$q54$, $q55$https://www.omannews.gov.om/topics/ar/7/show/474483$q55$, '2026-10-04 11:20:00+04'),
  ($q61$سلطنة عُمان تشارك في اجتماع اللجنة الوزارية المكلفة بمتابعة العمل المشترك لدول مجلس التعاون$q61$, $q62$شاركت السلطنة في الاجتماع السابع والعشرين للجنة الذي عُقد عبر الاتصال المرئي.$q62$, $q63$شاركت سلطنة عُمان في أعمال الاجتماع السابع والعشرين للجنة الوزارية المكلفة بمتابعة تنفيذ القرارات ذات العلاقة بالعمل المشترك لدول مجلس التعاون لدول الخليج العربية، والذي عُقد عبر الاتصال المرئي.$q63$, 'oman', $q64$وكالة الأنباء العُمانية$q64$, $q65$https://www.omannews.gov.om/topics/ar/3/show/474520$q65$, '2026-10-04 11:12:00+04'),
  ($q71$إعلان الفائزين بجائزة ثقافة الطفل لعام 2026$q71$, $q72$أعلنت وزارة الثقافة والرياضة والشباب أسماء الفائزين في فرعي الجائزة: «تحدّث كي أراك» للأطفال، و«عُمان تحكي» للكتّاب.$q72$, $q73$أعلنت وزارة الثقافة والرياضة والشباب أسماء الفائزين بجائزة ثقافة الطفل لعام 2026م في فرعيها: «تحدّث كي أراك» الموجّه للأطفال، وقد أُعلنت أسماء الفائزين بمراكزه الخمسة الأولى، و«عُمان تحكي» الموجّه للكتّاب والأدباء المتخصصين في ثقافة الطفل.

وفازت في فرع «عُمان تحكي» وفاء بنت جمعة الراشدية عن قصة «سالم والعود القادم من البحر» التي تناولت سيرة الفنان سالم بن راشد الصوري.$q73$, 'oman', $q74$وكالة الأنباء العُمانية$q74$, $q75$https://www.omannews.gov.om/topics/ar/3/show/474494$q75$, '2026-10-04 11:04:00+04'),
  ($q81$الجمعية العُمانية للفلك والفضاء تحتفي بأسبوع الفضاء العالمي$q81$, $q82$تنظّم الجمعية فعاليات بمناسبة أسبوع الفضاء العالمي الذي يستمر حتى 10 أكتوبر.$q82$, $q83$تحتفي الجمعية العُمانية للفلك والفضاء بأسبوع الفضاء العالمي الذي يستمر حتى 10 أكتوبر، بهدف نشر الوعي بإسهامات علوم الفضاء وتقنياته في الحياة اليومية.$q83$, 'oman', $q84$وكالة الأنباء العُمانية$q84$, $q85$https://omannews.gov.om/topics/ar/86/show/474509$q85$, '2026-10-04 10:56:00+04'),
  ($q91$دراسة عُمانية: مياه الصرف المعالَجة تُظهر نتائج واعدة لري المزارع$q91$, $q92$دراسة استمرت ثماني سنوات رصدت نموًّا سليمًا وإنتاجًا جيدًا لأشجار الليمون المروية بمياه صرف معالَجة معالجة ثلاثية.$q92$, $q93$كشفت دراسة استمرت ثماني سنوات، أجرتها وزارة الثروة الزراعية والسمكية وموارد المياه بالتعاون مع شركة نماء لخدمات المياه، عن نموّ سليم وإنتاج جيّد لأشجار الليمون المروية بمياه صرف صحي معالَجة معالجة ثلاثية.

وتأتي الدراسة ضمن الجهود المبذولة لاستكشاف إمكانية دعم الزراعة المستدامة بمياه الصرف المعالَجة.$q93$, 'oman', $q94$مسقط ديلي$q94$, $q95$https://www.muscatdaily.com/2026/10/04/treated-wastewater-shows-promise-for-omans-farms/$q95$, '2026-10-04 10:48:00+04'),
  ($q101$أكتوبر يحمل أجواءً أبرد وأمطارًا وتنبيهات في سلطنة عُمان$q101$, $q102$تراجعت درجات الحرارة العظمى في السلطنة إلى ما دون 40 درجة مئوية، وسُجّلت أمطار في الأول من أكتوبر.$q102$, $q103$شهدت سلطنة عُمان مع بداية أكتوبر تحوّلًا ملحوظًا في الأجواء، إذ تراجعت درجات الحرارة العظمى في مختلف أنحاء السلطنة إلى ما دون 40 درجة مئوية.

وسُجّل أعلى هطول للأمطار في الأول من أكتوبر بولاية دماء والطائيين بنحو 27 ملم، تلاها الجبل الأخضر بنحو 20 ملم.$q103$, 'oman', $q104$أوبزرفر عُمان$q104$, $q105$https://www.omanobserver.om/article/1197202/oman/weather/october-brings-cooler-weather-rain-and-alerts-across-oman$q105$, '2026-10-04 10:40:00+04'),
  ($q111$احتجاجات طلابية في فرنسا: إغلاق كلّي أو جزئي لما يصل إلى 500 مدرسة الإثنين$q111$, $q112$أعلنت وزيرة التعليم الفرنسية تعليق الدروس كليًّا أو جزئيًّا في 400 إلى 500 مدرسة ثانوية بعد احتجاجات على نقص المعلمين وتهالك المباني.$q112$, $q113$أعلنت وزيرة التعليم الفرنسية أن الدروس ستُعلَّق كليًّا أو جزئيًّا في ما بين 400 و500 مدرسة ثانوية يوم الإثنين، بعد أيام من احتجاجات طلابية، بعضها عنيف، على نقص المعلمين وتهالك المباني واكتظاظ الفصول.

وبدأت الحركة قبل أسبوعين من ثانوية سان-إكزوبيري في كريتاي بضواحي باريس، دعمًا لمعلمين مضربين احتجّوا على نقص الكوادر والموارد. وقالت الوزيرة إن 24 مدرسة أُحرقت أو نُهبت منذ بدء الحركة، وإن 78 من العاملين في التعليم أُصيبوا.$q113$, 'world', $q114$يورونيوز$q114$, $q115$https://www.euronews.com/2026/10/04/student-protests-in-france-400500-schools-fully-or-partially-closed-monday$q115$, '2026-10-04 11:56:00+04'),
  ($q121$فيضانات كتالونيا: قتيلان ومفقود بعد أمطار قياسية$q121$, $q122$لقي شخصان مصرعهما وفُقد ثالث في أمطار غزيرة وفيضانات ضربت إقليم كتالونيا شمال شرق إسبانيا.$q122$, $q123$لقي شخصان مصرعهما وفُقد ثالث إثر أمطار غزيرة وفيضانات ضربت إقليم كتالونيا شمال شرق إسبانيا. توفي رجل في الخامسة والستين في بلدة تورديرا إثر انهيار جدار في مخيم، وغرق آخر في مرأب غمرته المياه في مونتورنيس ديل فاليس، فيما تواصل فرق الطوارئ البحث عن مفقود في بلدة بينيدا دي مار.

وسجّلت برشلونة أكثر أيامها مطرًا منذ بدء الرصد عام 1883، وأصدرت السلطات الكتالونية إنذارًا أحمر ودعت السكان إلى البقاء في منازلهم.$q123$, 'world', $q124$فرانس 24$q124$, $q125$https://www.france24.com/en/live-news/20261004-two-dead-in-catalonia-due-to-torrential-rains-spanish-officials$q125$, '2026-10-04 11:48:00+04'),
  ($q131$اختتام دورة الألعاب الآسيوية في آيتشي-ناغويا وقطر تتسلّم الراية$q131$, $q132$أُسدل الستار على الدورة العشرين بحفل ختام أعلنه رئيس المجلس الأولمبي الآسيوي، وتصدّرت الصين جدول الميداليات.$q132$, $q133$أُسدل الستار الأحد 4 أكتوبر على دورة الألعاب الآسيوية العشرين في آيتشي-ناغويا باليابان بحفل ختام استمر نحو تسعين دقيقة، أعلن خلاله رئيس المجلس الأولمبي الآسيوي الشيخ جوعان بن حمد آل ثاني اختتام الدورة.

وتصدّرت الصين جدول الميداليات، تلتها اليابان ثم كوريا الجنوبية. وتستضيف قطر النسخة المقبلة من الألعاب.$q133$, 'world', $q134$آوتلوك إنديا$q134$, $q135$https://www.outlookindia.com/sports/others/closing-ceremony-aichi-nagoya-asian-games-2026-neeru-dhanda-india$q135$, '2026-10-04 11:40:00+04'),
  ($q141$فيرستابن يفوز بسباق جائزة البحرين الكبرى المقام في ماليزيا$q141$, $q142$حقق ماكس فيرستابن أول فوز له هذا الموسم في سباق شهد أمطارًا غزيرة، وحلّ كيمي أنتونيلي ثانيًا.$q142$, $q143$حقق السائق ماكس فيرستابن وفريقه ريد بُل أول فوز لهما هذا الموسم في سباق جائزة البحرين الكبرى المقام في ماليزيا، بعد سباق شهد أمطارًا وتأخيرًا. وحلّ كيمي أنتونيلي ثانيًا بفارق 2.307 ثانية، فيما انسحب جورج راسل في مرحلة متأخرة من السباق، وهو ما عزّز موقع أنتونيلي في صراع لقب السائقين.$q143$, 'world', $q144$الموقع الرسمي للفورمولا 1$q144$, $q145$https://www.formula1.com/en/latest/article/verstappen-wins-rain-hit-bahrain-gp-in-malaysia-over-antonelli-as-russell-retires-late-on.6qfpIHPch8mIVj2YgfHdCp$q145$, '2026-10-04 11:32:00+04'),
  ($q151$اختتام الأولمبياد الدولي للفلك والفيزياء الفلكية في هانوي بجوائز للجزائر والسعودية$q151$, $q152$اختُتمت الدورة التاسعة عشرة في العاصمة الفيتنامية، وستستضيف تركيا الدورة المقبلة عام 2027.$q152$, $q153$اختُتمت في العاصمة الفيتنامية هانوي الأحد 4 أكتوبر الدورة التاسعة عشرة من الأولمبياد الدولي للفلك والفيزياء الفلكية. وتصدّرت إيران بخمس ميداليات ذهبية لطلابها الخمسة، ووزّعت اللجنة المنظمة 51 ميدالية ذهبية و48 فضية و60 برونزية و22 شهادة تقدير.

وحصدت الجزائر والسعودية جوائز في المسابقة. وسلّمت فيتنام راية الدورة العشرين إلى تركيا التي تستضيفها عام 2027.$q153$, 'world', $q154$الجزيرة نت$q154$, $q155$https://www.aljazeera.net/science/2026/10/4/%D8%A7%D9%84%D8%AC%D8%B2%D8%A7%D8%A6%D8%B1-%D9%88%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9-%D8%AA%D8%AD%D8%B5%D8%AF%D8%A7%D9%86-%D8%AC%D9%88%D8%A7%D8%A6%D8%B2-%D9%81%D9%8A$q155$, '2026-10-04 11:24:00+04'),
  ($q161$علماء يكشفون كيف يضيف الدماغ معلومات جديدة إلى الذكريات القائمة$q161$, $q162$دراسة إسبانية على الفئران تكشف دور نوع من الخلايا العصبية في الحُصين يحمي الذكريات القديمة عند تخزين الجديد.$q162$, $q163$كشفت دراسة مشتركة لثلاث مؤسسات إسبانية، أجراها معهد علوم الأعصاب التابع للمجلس الأعلى للأبحاث العلمية وجامعة ميغيل هرنانديز ونُشرت في مجلة «بلوس بيولوجي»، أن نوعًا محددًا من الخلايا العصبية في التلفيف المسنّن بالحُصين يثبّط نشاط خلايا أخرى، ليتيح دمج التجارب الجديدة دون المساس بالذكريات القائمة.

وأُجريت التجارب على الفئران، ووجد الباحثون أن انخفاض مستوى التثبيط عن المعتاد ارتبط بسلوك أقرب إلى استرجاع أفضل للذاكرة وتذكّر أدقّ، لكن لا توجد مستويات تثبيط ثابتة أفضل من غيرها في الحفاظ على أكبر قدر من المعلومات.$q163$, 'world', $q164$يورونيوز$q164$, $q165$https://www.euronews.com/2026/10/04/researchers-discover-how-the-brain-updates-memories-with-new-information$q165$, '2026-10-04 11:16:00+04'),
  ($q171$مزارعو الاتحاد الأوروبي بين تراجع أسعار المنتجات وارتفاع تكاليف الوقود والأسمدة$q171$, $q172$تراجعت أسعار الإنتاج الزراعي في الاتحاد الأوروبي 5.8% سنويًّا في الربع الثاني، بينما ارتفعت تكاليف الطاقة والأسمدة.$q172$, $q173$تراجعت أسعار الإنتاج الزراعي في الاتحاد الأوروبي بنسبة 5.8% على أساس سنوي في الربع الثاني من 2026، وهو الربع الثالث على التوالي من التراجع، وسجّلت أسعار الحليب هبوطًا بنسبة 16.6% والحبوب 5.6%.

وفي المقابل ارتفعت أسعار الطاقة والزيوت 22% والأسمدة ومحسّنات التربة 13.4%. وكانت المفوضية الأوروبية قد أعلنت في 17 يوليو تخصيص 540 مليون يورو لتعويض المزارعين الأكثر تضررًا.$q173$, 'world', $q174$يورونيوز$q174$, $q175$https://www.euronews.com/2026/10/02/eu-farmers-face-falling-produce-prices-as-fuel-and-fertiliser-costs-rise$q175$, '2026-10-04 11:08:00+04'),
  ($q181$انطلاق إعلان جوائز نوبل 2026 يوم الإثنين$q181$, $q182$تبدأ جوائز نوبل بإعلان الفسيولوجيا أو الطب الإثنين 5 أكتوبر، وتُختتم بالاقتصاد في 12 أكتوبر.$q182$, $q183$تبدأ مؤسسة نوبل الإثنين 5 أكتوبر إعلان جوائز 2026 بجائزة الفسيولوجيا أو الطب من معهد كارولينسكا، ثم الفيزياء في 6 أكتوبر، والكيمياء في 7 أكتوبر، والأدب في 8 أكتوبر، والسلام في 9 أكتوبر. وتُختتم الإعلانات بجائزة الاقتصاد في 12 أكتوبر.$q183$, 'world', $q184$موقع جائزة نوبل$q184$, $q185$https://www.nobelprize.org/prizes/about/prize-announcement-dates/$q185$, '2026-10-04 11:00:00+04'),
  ($q191$وصول طاقم «كرو-13» إلى محطة الفضاء الدولية$q191$, $q192$أطلقت سبيس إكس مهمة «كرو-13» لصالح ناسا الخميس، وانضم أفراد الطاقم الأربعة إلى المحطة في اليوم نفسه.$q192$, $q193$أطلقت سبيس إكس مهمة «كرو-13» لصالح ناسا الخميس 1 أكتوبر، وارتبطت المركبة بمحطة الفضاء الدولية في اليوم نفسه. ويضم الطاقم رائدة ناسا جيسيكا واتكينز ورائد ناسا لوك ديلاني ورائد وكالة الفضاء الكندية جوشوا كوتريك ورائد روسكوسموس سيرغي تيتيريتنيكوف.

وسيساعد الطاقم الباحثين في دراسة أنسجة مشتقة من خلايا جذعية بشرية للمساهمة في علاج أمراض القلب وباركنسون. ومن المقدّر أن يغادر طاقم «كرو-12» المحطة عائدًا إلى الأرض في 7 أكتوبر.$q193$, 'world', $q194$سبيس دوت كوم$q194$, $q195$https://www.space.com/news/live/spacex-nasa-crew-13-astronauts-launch-to-iss-october-1-2026$q195$, '2026-10-04 10:52:00+04')
) as v(title, summary, body, scope, source, url, published_at)
where not exists (select 1 from public.news n where n.url = v.url);

select count(*) as "الأخبار المنشورة اليوم"
from public.news where published_at >= '2026-10-04 00:00:00+04' and published_at < '2026-10-05 00:00:00+04';
